use std::{fs,path::Path,collections::BTreeMap};use sha2::{Digest,Sha256};use serde_json::json;
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn tree(src:&Path,dst:&Path,root:&Path,index:&mut BTreeMap<String,String>){fs::create_dir_all(dst).unwrap();for e in fs::read_dir(src).unwrap(){let p=e.unwrap().path();let to=dst.join(p.file_name().unwrap());if p.is_dir(){tree(&p,&to,root,index)}else{fs::copy(&p,&to).unwrap();assert_eq!(hash(&p),hash(&to));assert!(index.insert(to.strip_prefix(root).unwrap().to_str().unwrap().into(),hash(to)).is_none());}}}
fn main(){let r=Path::new("/tmp/zopro-local-difference-basis");let report=Path::new("/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-26-local-difference-basis");let dst=report.join("artifacts");assert!(!dst.exists());fs::create_dir(&dst).unwrap();let mut index=BTreeMap::new();for name in ["experiment.json","implement.rs","stats.rs.txt","native-helpers.rs","probe-initial.rs","repair-link.rs","link-repair.json","input-pins-v2.json","plan-v2.json","run-v2.log","cases.json","probe.rs","prepare.rs","plan.json","input-pins.json","run.log","closeout.rs","results.json","publish.rs"]{fs::copy(r.join(name),dst.join(name)).unwrap();assert_eq!(hash(r.join(name)),hash(dst.join(name)));index.insert(name.into(),hash(dst.join(name)));}tree(&r.join("run"),&dst.join("run"),&dst,&mut index);tree(&r.join("run-v2"),&dst.join("run-v2"),&dst,&mut index);fs::write(dst.join("SHA256SUMS"),index.iter().map(|(p,h)|format!("{h}  {p}\n")).collect::<String>()).unwrap();fs::write(dst.join("artifact-index.json"),serde_json::to_vec_pretty(&json!({"files":index.len(),"sha256":index,"executable_sha256":hash(r.join("probe")),"executable_local_path":r.join("probe"),"source_and_library_identity":"input-pins.json","no_witness_scalar_or_proof_arrays_exported":true,"scope":"Read-only lossless local difference-basis metadata census, no performance claim"})).unwrap()).unwrap();println!("Published{}textartifacts",index.len());}
